using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using UnityEngine;using UnityEngine.SceneManagement;using UnityEditor;using UnityEditor.SceneManagement;
[InitializeOnLoad] public static class Street3GapReview {
 const string PlayKey="Street3.GapReview.Play",BuildKey="Street3.GapReview.Build";static IEnumerator routine;static int updates;static Report report;static bool building;
 [Serializable] public class Row {public string name;public bool baseline,reduced,finished,resetClean,resetChecked,launchClean,pauseStable;public float angle,power,claw,wallSeconds,firstCityTime=-1,firstCityX=-1,lastWallTime=-1,wallToCityGap=-1,maxHold,distance,shardBoundsError,shardEnergyExcess;public int maxFragments,maxCityFragments,maxVfx,cityBreaks,secondaryBreaks,colliders;public FlightState result;public WorldBreakEvent[] breaks;public FlightGameEvent[] events;public string[] frames;}
 [Serializable] public class Report {public string revision="crab-flight-street3-gap1-r1",state="RUNNING",error="",scope="Actual Play mode. Frozen street3 layout versus first6 per direction shifted5m downstream. Same presentation/physics/charge/counts. Original replay residual remains; not a Scene lifetime diagnosis.";public int unitChecks;public List<Row> runs=new List<Row>();public string webBuild="NOT_STARTED";}
 static Street3GapReview(){EditorApplication.update+=Poll;}
 public static void Begin(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Play already active");var g=BuildFlight.PrepareScene();g.enabled=false;EditorSceneManager.SaveScene(g.gameObject.scene,"Assets/FlightField.unity");SessionState.SetBool(PlayKey,true);EditorApplication.EnterPlaymode();}
 static void Poll(){
  if(routine!=null){try{if(!routine.MoveNext()){routine=null;SessionState.SetBool(BuildKey,true);EditorApplication.ExitPlaymode();}}catch(Exception e){Fail(e);}return;}
  if(SessionState.GetBool(PlayKey,false)&&EditorApplication.isPlaying&&!EditorApplication.isCompiling&&UnityEngine.Object.FindFirstObjectByType<CrabFlightGame>()&&++updates>3){SessionState.SetBool(PlayKey,false);routine=Run();return;}
  if(!building&&SessionState.GetBool(BuildKey,false)&&!EditorApplication.isPlayingOrWillChangePlaymode&&!EditorApplication.isCompiling){SessionState.SetBool(BuildKey,false);building=true;try{Build();EditorApplication.Exit(0);}catch(Exception e){Fail(e);}}
 }
 static void Fail(Exception e){if(report==null&&File.Exists("../evidence/native-result.json"))report=JsonUtility.FromJson<Report>(File.ReadAllText("../evidence/native-result.json"));if(report==null)report=new Report();report.error=e.GetType().Name+": "+e.Message;report.state="FAILED";Save();routine=null;EditorApplication.Exit(1);}
 static void Units(){
  var c=new ImpactStop();c.Request(1,1,"destruction","wood",1,false,0);float light=c.Remaining;c.Request(1,2,"destruction","metal",1,false,1);if(c.Remaining<=light||c.Remaining>.055f||c.Requests!=1)throw new Exception("burst promotion");report.unitChecks++;
  c.Request(1,2,"destruction","metal",1,false,1);if(c.Requests!=1)throw new Exception("duplicate stop");report.unitChecks++;
  c.Reset();for(int i=1;i<=2000;i++){c.Request(2,i,"destruction","metal",1,false,1);c.Filter(.005f);}if(c.TotalFrozen>1.32f||c.Remaining>.055f)throw new Exception("rolling stop budget");report.unitChecks++;
  c.Reset();c.Request(3,1,"destruction","wall",1,true,1);if(c.Remaining>.02751f)throw new Exception("reduced stop");c.Reset();if(c.Remaining!=0||c.Requests!=0)throw new Exception("reset stop");report.unitChecks++;
 }
 static IEnumerator Run(){
  Directory.CreateDirectory("../evidence/native");report=new Report();Units();Save();var template=UnityEngine.Object.FindFirstObjectByType<CrabFlightGame>();template.enabled=false;
  string oldLayout=File.ReadAllText("Assets/Editor/Street3BeforeGapLayout.json"),newLayout=Resources.Load<TextAsset>("CityDensityR2/CityPlacementDense").text;
  var cases=new[]{new Case("before-1",true,false,12,100,45,1),new Case("gap-1",false,false,12,100,45,1),new Case("before-2",true,false,12,100,45,1),new Case("gap-2",false,false,12,100,45,1),new Case("before-3",true,false,12,100,45,1),new Case("gap-3",false,false,12,100,45,1),new Case("gap-reduced",false,true,12,100,45,1),new Case("gap-low",false,false,12,70,45,1),new Case("gap-high",false,false,28,100,45,1),new Case("gap-left",false,false,12,100,45,-1)};
  foreach(var test in cases){
   Street3Presentation.ReviewBaseline=false;City2Data.ReviewSetLayout(test.baseline?oldLayout:newLayout);CrabModel.ReviewUseBaseline(false);
   var scene=SceneManager.CreateScene("Street3 playback "+test.name);SceneManager.SetActiveScene(scene);var g=new GameObject("CrabFlightGame").AddComponent<CrabFlightGame>();g.enabled=false;Copy(template,g);g.Initialize();g.SetReducedMotion(test.reduced?"1":"0");g.Configure(JsonUtility.ToJson(new FlightSettings{claw=test.claw,shell=45,legs=45,angle=test.angle,power=test.power}));yield return null;yield return null;
   if(test.name=="before-1"||test.name=="gap-1"){
    var c=g.ReviewCamera;var pos=c.transform.position;var rot=c.transform.rotation;float size=c.orthographicSize,aspect=c.aspect;
    c.transform.position=new Vector3(42,9,-20);c.transform.rotation=Quaternion.LookRotation(new Vector3(0,-5.3f,16),Vector3.up);c.orthographicSize=8;Capture(g,"../evidence/native/"+test.name+"-layout-844.png",844,390,false);Capture(g,"../evidence/native/"+test.name+"-layout-390.png",390,844,false);c.transform.SetPositionAndRotation(pos,rot);c.orthographicSize=size;c.aspect=aspect;
   }
   g.BeginAim("");g.PreviewLaunch(JsonUtility.ToJson(new FlightAimInput{angle=test.angle,power=test.power,direction=test.direction,eligible=true}));g.BeginSpinCharge("");for(int i=0;i<601;i++){g.AddSpinWork(JsonUtility.ToJson(new SpinWorkInput{distance=2f/60,seconds=1f/60,direction=test.direction}));g.Tick(1f/60);}if(!g.State().chargeReady||g.State().chargeEnergy<.999f)throw new Exception("active charge");
   g.ReleaseLaunch(JsonUtility.ToJson(new FlightAimInput{angle=test.angle,power=test.power,direction=test.direction,eligible=true}));var row=Finish(g,test.name,test);report.runs.Add(row);Save();
   if(test.name=="gap-3")for(int retry=0;retry<2;retry++){g.RetryLaunch("");var again=Finish(g,test.name+"-retry"+retry,test);report.runs.Add(again);Save();yield return null;yield return null;}
   g.Prepare("");yield return null;yield return null;var reset=g.State();row.resetChecked=true;row.resetClean=reset.fragments==0&&reset.cityFragments==0&&reset.vfxActive==0&&reset.hitStopRequests==0&&reset.hitStopRemaining==0;if(!row.resetClean)throw new Exception("reset retained effects");g.ShutdownReviewPhysics();yield return null;yield return null;SceneManager.SetActiveScene(template.gameObject.scene);var clear=SceneManager.UnloadSceneAsync(scene);while(!clear.isDone)yield return null;Save();
  }
  Street3Presentation.ReviewBaseline=false;City2Data.ReviewSetLayout(newLayout);report.state="NATIVE_COMPLETED";Save();
 }
 sealed class Case {public string name;public bool baseline,reduced;public float angle,power,claw;public int direction;public Case(string n,bool b,bool r,float a,float p,float c,int d){name=n;baseline=b;reduced=r;angle=a;power=p;claw=c;direction=d;}}
 static void Copy(CrabFlightGame from,CrabFlightGame to){to.crabShader=from.crabShader;to.groundShader=from.groundShader;to.cityLayout=2;to.secondaryThresholdFraction=from.secondaryThresholdFraction;to.cityR2Shader=from.cityR2Shader;to.cityR2Albedo=from.cityR2Albedo;to.cityR2Metal=from.cityR2Metal;to.effectsPrefab=from.effectsPrefab;}
 static Row Finish(CrabFlightGame g,string name,Case test){
  var begin=g.State();var row=new Row{name=name,baseline=test.baseline,reduced=test.reduced,angle=test.angle,power=test.power,claw=test.claw,pauseStable=true,launchClean=begin.fragments==0&&begin.cityFragments==0&&begin.time==0&&begin.hitStopRemaining==0,colliders=g.ReviewSimulation.ColliderCount};var frames=new List<string>();bool capturedExit=false,capturedStreet=false,capturedClear=false,paused=false;float wall=0;
  for(int i=0;i<6000&&!g.Finished;i++){
   g.Tick(1f/60);wall+=1f/60;var s=g.State();row.maxHold=Mathf.Max(row.maxHold,s.hitStopRemaining);row.maxFragments=Mathf.Max(row.maxFragments,s.fragments);row.maxCityFragments=Mathf.Max(row.maxCityFragments,s.cityFragments);row.maxVfx=Mathf.Max(row.maxVfx,s.vfxActive);
   var city=g.ReviewSimulation.BreakEvents.FirstOrDefault(e=>e.id.StartsWith("street3-"));if(city!=null&&row.firstCityTime<0){row.firstCityTime=city.time;row.firstCityX=city.position.x;}
   if(!paused&&s.hitStopRemaining>0){float before=s.time,hold=s.hitStopRemaining;var position=g.ReviewSimulation.Body.position;g.SetPaused("1");g.Tick(.25f);row.pauseStable=g.State().time==before&&g.State().hitStopRemaining==hold&&g.ReviewSimulation.Body.position==position;g.SetPaused("0");paused=true;}
   if(!capturedExit&&Mathf.Abs(s.worldX)>27&&s.wallsBroken>0){string path="../evidence/native/"+name+"-exit-390.png";Capture(g,path,390,844,true);frames.Add(path);capturedExit=true;}
   if(!capturedClear&&Mathf.Abs(s.worldX)>30){string path="../evidence/native/"+name+"-reveal-390.png";Capture(g,path,390,844,true);frames.Add(path);capturedClear=true;}
   if(!capturedStreet&&Mathf.Abs(s.worldX)>39){foreach(var dims in new[]{new[]{390,844},new[]{844,390}}){string path="../evidence/native/"+name+"-street-"+dims[0]+".png";Capture(g,path,dims[0],dims[1],true);frames.Add(path);}capturedStreet=true;}
  }
  row.shardBoundsError=g.ReviewSimulation.ReviewShardVisualBoundsError;row.shardEnergyExcess=g.ReviewSimulation.ReviewShardEnergyExcess;row.result=g.State();row.distance=row.result.distance;row.finished=g.Finished&&row.result.physicsFault=="";row.wallSeconds=wall;row.breaks=g.ReviewSimulation.BreakEvents.ToArray();row.events=g.ReviewEvents;row.lastWallTime=row.breaks.Where(e=>e.id.StartsWith("outer-wall-")&&e.time<=row.firstCityTime).Select(e=>e.time).DefaultIfEmpty(-1).Max();row.wallToCityGap=row.firstCityTime>=0&&row.lastWallTime>=0?row.firstCityTime-row.lastWallTime:-1;row.cityBreaks=row.breaks.Count(e=>e.id.StartsWith("street3-"));row.secondaryBreaks=g.ReviewSimulation.CitySecondaryBreaks;row.frames=frames.ToArray();
  if(row.shardBoundsError>.0001f||row.shardEnergyExcess>.01f||!row.finished||!row.launchClean||row.colliders!=13||!row.pauseStable||row.maxHold>.05501f||row.maxFragments>48||row.maxCityFragments>20||row.maxVfx>320||!row.result.compoundFrozen)throw new Exception("playback regression "+name+" "+row.result.physicsFault);
  return row;
 }
 static void Capture(CrabFlightGame g,string path,int w,int h,bool follow){
  var c=g.ReviewCamera;float aspect=c.aspect,ortho=c.orthographicSize;var p=c.transform.position;var q=c.transform.rotation;var previous=RenderTexture.active;c.aspect=(float)w/h;if(follow)g.RefreshReviewCamera();var rt=new RenderTexture(w,h,24);c.targetTexture=rt;c.Render();RenderTexture.active=rt;var tex=new Texture2D(w,h,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,w,h),0,0);tex.Apply();File.WriteAllBytes(path,tex.EncodeToPNG());c.targetTexture=null;RenderTexture.active=previous;rt.Release();UnityEngine.Object.Destroy(rt);UnityEngine.Object.Destroy(tex);c.aspect=aspect;c.orthographicSize=ortho;c.transform.SetPositionAndRotation(p,q);
 }
 static void Build(){if(report==null)report=JsonUtility.FromJson<Report>(File.ReadAllText("../evidence/native-result.json"));CrabModel.ReviewUseBaseline(false);Street3Presentation.ReviewBaseline=false;string target="../delivery/UnityWeb/street3-gap1-r1";report.webBuild="BUILDING";Save();BuildFlight.Web(target);foreach(string name in new[]{"launch-input.js","sound-pack.js"})File.Copy("../web-template/"+name,target+"/"+name,true);CopyTree("../web-template/SoundPack",target+"/SoundPack");report.webBuild="SUCCEEDED";report.state="BUILD_AND_NATIVE_COMPLETED";Save();}
 static void CopyTree(string from,string to){Directory.CreateDirectory(to);foreach(var file in Directory.GetFiles(from))File.Copy(file,Path.Combine(to,Path.GetFileName(file)),true);foreach(var dir in Directory.GetDirectories(from))CopyTree(dir,Path.Combine(to,Path.GetFileName(dir)));}
 static void Save(){Directory.CreateDirectory("../evidence");File.WriteAllText("../evidence/native-result.json",JsonUtility.ToJson(report,true));}
}
